import { Chess } from 'chess.js';

/** A named opening: its ECO code (A00 to E99) and its name, as in the Lichess openings dataset. */
export interface Opening {
  eco: string;
  name: string;
}

/** The deepest named opening of a game, and the ply (half-move count) of the position that matched it. */
export interface OpeningMatch extends Opening {
  ply: number;
}

/** Opening names by EPD, as generated by scripts/build-openings.mjs: [eco, name]. */
export type OpeningTable = Readonly<Record<string, readonly [string, string]>>;

/**
 * The EPD of a position: its FEN without the halfmove clock and move number, so the same position reached by
 * another move order, or at another move number, has the same key.
 */
export function epd(fen: string): string {
  return fen.split(' ').slice(0, 4).join(' ');
}

/** The FEN of every position of a game, from the start through each SAN move; stops at an illegal move. */
export function gameFens(startFen: string, sans: readonly string[]): string[] {
  const game = new Chess(startFen);
  const fens = [game.fen()];
  for (const san of sans) {
    try {
      game.move(san);
    } catch {
      break;
    }
    fens.push(game.fen());
  }
  return fens;
}

/**
 * The deepest known opening of a game, given the FEN of every position in it (index 0 the start, index n the
 * position after n plies). Positions after the game leaves the book still count, so a transposition back into a
 * known line is found. Null when no position has a name.
 */
export function findOpening(table: OpeningTable, fens: readonly string[]): OpeningMatch | null {
  for (let ply = fens.length - 1; ply >= 0; ply--) {
    const entry = table[epd(fens[ply] ?? '')];
    if (entry) return { eco: entry[0], name: entry[1], ply };
  }
  return null;
}
